"""Applies Collabook settings to the Android project generated by `flutter create`.

Run from the repo root after `flutter create --platforms=android ...`.
"""
import glob
import os
import re
import shutil

ROOT = os.getcwd()


def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def write(p, s):
    with open(p, "w", encoding="utf-8") as f:
        f.write(s)


# ---------- app/build.gradle(.kts): minSdk + permanent release signing ----------
kts = os.path.join(ROOT, "android/app/build.gradle.kts")
groovy = os.path.join(ROOT, "android/app/build.gradle")
if os.path.exists(kts):
    s = read(kts)
    s = s.replace("minSdk = flutter.minSdkVersion", "minSdk = 23")
    if "keystoreProperties" not in s:
        header = (
            "val keystoreProperties = java.util.Properties().apply {\n"
            "    val f = rootProject.file(\"../tool/signing/key.properties\")\n"
            "    if (f.exists()) f.inputStream().use { load(it) }\n"
            "}\n\n"
        )
        # after the plugins { } block
        m = re.search(r"plugins\s*\{[^}]*\}\s*", s)
        s = s[: m.end()] + "\n" + header + s[m.end():] if m else header + s
        signing = (
            "    signingConfigs {\n"
            "        create(\"release\") {\n"
            "            keyAlias = keystoreProperties[\"keyAlias\"] as String\n"
            "            keyPassword = keystoreProperties[\"keyPassword\"] as String\n"
            "            storeFile = rootProject.file(\"../tool/signing/collabook.jks\")\n"
            "            storePassword = keystoreProperties[\"storePassword\"] as String\n"
            "        }\n"
            "    }\n\n"
            "    buildTypes {"
        )
        s = s.replace("    buildTypes {", signing, 1)
        s = s.replace('signingConfig = signingConfigs.getByName("debug")', 'signingConfig = signingConfigs.getByName("release")')
    write(kts, s)
    print("patched", kts)
elif os.path.exists(groovy):
    s = read(groovy)
    s = s.replace("minSdkVersion flutter.minSdkVersion", "minSdkVersion 23")
    if "keystoreProperties" not in s:
        s = (
            "def keystoreProperties = new Properties()\n"
            "def kp = rootProject.file('../tool/signing/key.properties')\n"
            "if (kp.exists()) { keystoreProperties.load(new FileInputStream(kp)) }\n\n" + s
        )
        s = s.replace(
            "    buildTypes {",
            "    signingConfigs {\n        release {\n"
            "            keyAlias keystoreProperties['keyAlias']\n"
            "            keyPassword keystoreProperties['keyPassword']\n"
            "            storeFile rootProject.file('../tool/signing/collabook.jks')\n"
            "            storePassword keystoreProperties['storePassword']\n"
            "        }\n    }\n\n    buildTypes {",
            1,
        )
        s = s.replace("signingConfig signingConfigs.debug", "signingConfig signingConfigs.release")
    write(groovy, s)
    print("patched", groovy)

# ---------- manifest: label, no cloud backup, internet ----------
man = os.path.join(ROOT, "android/app/src/main/AndroidManifest.xml")
s = read(man)
s = re.sub(r'android:label="[^"]*"', 'android:label="Collabook"', s)
if "android:allowBackup" not in s:
    s = s.replace("<application", '<application android:allowBackup="false"', 1)
if "android.permission.INTERNET" not in s:
    s = s.replace("<application", '<uses-permission android:name="android.permission.INTERNET"/>\n    <application', 1)
if "android.permission.USE_BIOMETRIC" not in s:
    s = s.replace("<application", '<uses-permission android:name="android.permission.USE_BIOMETRIC"/>\n    <application', 1)
write(man, s)

# ---------- MainActivity: FlutterFragmentActivity (needed for fingerprint) ----------
for p in glob.glob(os.path.join(ROOT, "android/app/src/main/kotlin/**/MainActivity.kt"), recursive=True):
    s = read(p)
    s = s.replace("io.flutter.embedding.android.FlutterActivity", "io.flutter.embedding.android.FlutterFragmentActivity")
    s = re.sub(r":\s*FlutterActivity\(\)", ": FlutterFragmentActivity()", s)
    write(p, s)
    print("patched", p)

# ---------- styles: AppCompat-free fragment activity still uses LaunchTheme; nothing to change ----------

# ---------- launcher icons ----------
for density in ["mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi"]:
    src = os.path.join(ROOT, "tool/icons", f"ic_launcher_{density}.png")
    dst_dir = os.path.join(ROOT, f"android/app/src/main/res/mipmap-{density}")
    if os.path.exists(src) and os.path.isdir(dst_dir):
        shutil.copy(src, os.path.join(dst_dir, "ic_launcher.png"))
print("icons copied")

shutil.copy(os.path.join(ROOT, "tool/proguard-rules.pro"), os.path.join(ROOT, "android/app/proguard-rules.pro"))
print("done")
